# must / mustnot: tool names checked deterministically; `expect` is graded by an LLM judge.
SEED = [
    {"id": 101, "description": "omleta 2 oua", "calories": 220, "date": "today"},
    {"id": 102, "description": "gin tonic", "calories": 1, "date": "today"},
    {"id": 103, "description": "paste carbonara", "calories": 650, "date": "today"},
]
DUP = [
    {"id": 201, "description": "pizza margherita", "calories": 800, "date": "today"},
    {"id": 202, "description": "pizza margherita", "calories": 800, "date": "today"},
]
